var s=findScreen();var b=s.layers.find(function(l){return l.name==='body'});var dock=b.layers.find(function(l){return l.name==='composer-dock'});if(dock){var i=dock.layers[0];var g=i.detach();g.name='composer';g.frame.width=358;g.horizontalSizing=sketch.FlexSizing.Fixed;var inner=g.layers[0];inner.frame.width=358;inner.horizontalSizing=sketch.FlexSizing.Fixed;var r=inner.layers.find(function(l){return l.name==='row'});r.frame.width=326;r.horizontalSizing=sketch.FlexSizing.Fixed;inner.layers.filter(function(l){return l.type==='Text'}).forEach(function(l){l.frame.width=326});r.layers.filter(function(l){return /^icon button/.test(l.name)}).forEach(function(l){H.link(l,'conversation')});var chip=r.layers.find(function(l){return l.name==='chip'});if(chip)H.link(chip,'conversation--menu');H.relayout(g);H.relayout(dock)};H.out({id:ID,app:APP,fixed:!!dock});